    sdl: "# Common scalars and types\nscalar DateTime\n\n# Error handling\ntype Error {\n  message: String!\n  code: String!\n  field: String\n}\n\n# Base types from SQLite schema\ntype Query {\n  # Placeholder - will be extended by other schema files\n  _empty: String\n}\n\ntype Mutation {\n  # Placeholder to extend in other schemas\n  _empty: String\n}\n\ntype Subscription {\n  # Real-time updates defined in subscriptions/realtime.graphql\n  _placeholder: String\n}\n\n# Common health types are now defined in system-queries.graphql\n\n# Event types for subscriptions\ntype TableDeletedEvent {\n  id: ID!\n  identifier: String!\n  deletedAt: DateTime!\n}\n\ntype NodeDeletedEvent {\n  id: ID!\n  tableId: ID!\n  content: String!\n  deletedAt: DateTime!\n}\n",
