    path: "src/presentation/graphql/schema/database-backup.graphql",
    sdl: "# ============================================================================\n# Database Backup & Restore Schema\n# ============================================================================\n\n# ============================================================================\n# INPUT TYPES\n# ============================================================================\n\n\"\"\"\nOptions for creating a database backup\n\"\"\"\ninput BackupDatabaseInput {\n  \"\"\"\n  Custom output path (default: ./backups/database/db_{timestamp}.sqlite)\n  \"\"\"\n  outputPath: String\n\n  \"\"\"\n  Enable gzip compression\n  \"\"\"\n  compress: Boolean\n\n  \"\"\"\n  Validate backup integrity after creation\n  \"\"\"\n  validate: Boolean\n\n  \"\"\"\n  Include Write-Ahead Log (WAL) file\n  \"\"\"\n  includeWAL: Boolean\n}\n\n\"\"\"\nOptions for restoring from backup\n\"\"\"\ninput RestoreDatabaseInput {\n  \"\"\"\n  Path to the backup file\n  \"\"\"\n  backupPath: String!\n\n  \"\"\"\n  Create safety backup before restore\n  \"\"\"\n  safetyBackup: Boolean\n\n  \"\"\"\n  Validate backup before restore\n  \"\"\"\n  validateBeforeRestore: Boolean\n\n  \"\"\"\n  Verify database after restore\n  \"\"\"\n  verifyAfterRestore: Boolean\n}\n\n\"\"\"\nOptions for backup retention policy\n\"\"\"\ninput BackupRetentionPolicyInput {\n  \"\"\"\n  Maximum number of backups to keep\n  \"\"\"\n  maxBackups: Int\n\n  \"\"\"\n  Maximum age in days\n  \"\"\"\n  maxAgeDays: Int\n\n  \"\"\"\n  Minimum free disk space in bytes\n  \"\"\"\n  minFreeSpaceBytes: Float\n}\n\n\"\"\"\nFilter for listing backups\n\"\"\"\ninput BackupListFilterInput {\n  \"\"\"\n  Backup type filter\n  \"\"\"\n  type: BackupType\n\n  \"\"\"\n  Only backups created after this date\n  \"\"\"\n  createdAfter: DateTime\n\n  \"\"\"\n  Only backups created before this date\n  \"\"\"\n  createdBefore: DateTime\n}\n\n# ============================================================================\n# OUTPUT TYPES\n# ============================================================================\n\n\"\"\"\nResult of database backup operation\n\"\"\"\ntype BackupDatabaseResult {\n  \"\"\"\n  Operation success status\n  \"\"\"\n  success: Boolean!\n\n  \"\"\"\n  Path to the backup file\n  \"\"\"\n  backupPath: String!\n\n  \"\"\"\n  Backup file size in bytes\n  \"\"\"\n  sizeBytes: Float!\n\n  \"\"\"\n  Operation duration in milliseconds\n  \"\"\"\n  duration: Float!\n\n  \"\"\"\n  SHA-256 checksum (if validation enabled)\n  \"\"\"\n  checksum: String\n\n  \"\"\"\n  Error messages\n  \"\"\"\n  errors: [String!]!\n\n  \"\"\"\n  Warning messages\n  \"\"\"\n  warnings: [String!]!\n}\n\n\"\"\"\nVerification results after restore\n\"\"\"\ntype RestoreVerification {\n  \"\"\"\n  Number of tables in restored database\n  \"\"\"\n  tablesCount: Int!\n\n  \"\"\"\n  Number of nodes in restored database\n  \"\"\"\n  nodesCount: Int!\n\n  \"\"\"\n  Number of relations in restored database\n  \"\"\"\n  relationsCount: Int!\n\n  \"\"\"\n  Whether checksum matches\n  \"\"\"\n  checksumMatch: Boolean!\n}\n\n\"\"\"\nResult of database restore operation\n\"\"\"\ntype RestoreDatabaseResult {\n  \"\"\"\n  Operation success status\n  \"\"\"\n  success: Boolean!\n\n  \"\"\"\n  Path to the restored database\n  \"\"\"\n  restoredPath: String!\n\n  \"\"\"\n  Path to safety backup (if created)\n  \"\"\"\n  safetyBackupPath: String\n\n  \"\"\"\n  Verification results\n  \"\"\"\n  verification: RestoreVerification\n\n  \"\"\"\n  Operation duration in milliseconds\n  \"\"\"\n  duration: Float!\n\n  \"\"\"\n  Error messages\n  \"\"\"\n  errors: [String!]!\n\n  \"\"\"\n  Warning messages\n  \"\"\"\n  warnings: [String!]!\n}\n\n\"\"\"\nIndividual backup item\n\"\"\"\ntype BackupItem {\n  \"\"\"\n  Backup file path\n  \"\"\"\n  path: String!\n\n  \"\"\"\n  File size in bytes\n  \"\"\"\n  sizeBytes: Float!\n\n  \"\"\"\n  Creation timestamp\n  \"\"\"\n  createdAt: DateTime!\n\n  \"\"\"\n  Backup type\n  \"\"\"\n  type: BackupType!\n\n  \"\"\"\n  SHA-256 checksum\n  \"\"\"\n  checksum: String\n\n  \"\"\"\n  Table identifier (for table backups)\n  \"\"\"\n  tableIdentifier: String\n\n  \"\"\"\n  Node count (for table backups)\n  \"\"\"\n  nodeCount: Int\n\n  \"\"\"\n  Whether backup is compressed\n  \"\"\"\n  compressed: Boolean!\n}\n\n\"\"\"\nResult of listing backups\n\"\"\"\ntype BackupListResult {\n  \"\"\"\n  List of file-level backups\n  \"\"\"\n  fileBackups: [BackupItem!]!\n\n  \"\"\"\n  List of table-level backups\n  \"\"\"\n  tableBackups: [BackupItem!]!\n\n  \"\"\"\n  Total number of backups\n  \"\"\"\n  totalCount: Int!\n\n  \"\"\"\n  Total size in bytes\n  \"\"\"\n  totalSizeBytes: Float!\n}\n\n\"\"\"\nResult of applying retention policy\n\"\"\"\ntype ApplyRetentionPolicyResult {\n  \"\"\"\n  List of deleted backup paths\n  \"\"\"\n  deletedBackups: [String!]!\n\n  \"\"\"\n  Error messages\n  \"\"\"\n  errors: [String!]!\n\n  \"\"\"\n  Number of backups deleted\n  \"\"\"\n  deletedCount: Int!\n\n  \"\"\"\n  Space freed in bytes\n  \"\"\"\n  spaceFreed: Float!\n}\n\n\"\"\"\nBackup metrics and statistics\n\"\"\"\ntype BackupMetrics {\n  \"\"\"\n  Total number of backups created\n  \"\"\"\n  totalBackups: Int!\n\n  \"\"\"\n  Timestamp of last backup\n  \"\"\"\n  lastBackupTime: DateTime\n\n  \"\"\"\n  Average backup duration in milliseconds\n  \"\"\"\n  averageBackupDuration: Float!\n\n  \"\"\"\n  Total size of all backups in bytes\n  \"\"\"\n  totalBackupSize: Float!\n\n  \"\"\"\n  Success rate percentage\n  \"\"\"\n  successRate: Float!\n\n  \"\"\"\n  List of recent failed backups\n  \"\"\"\n  failedBackups: [FailedBackupInfo!]!\n}\n\n\"\"\"\nInformation about failed backup\n\"\"\"\ntype FailedBackupInfo {\n  \"\"\"\n  Failure timestamp\n  \"\"\"\n  timestamp: DateTime!\n\n  \"\"\"\n  Table identifier (for table backups)\n  \"\"\"\n  tableIdentifier: String\n\n  \"\"\"\n  Error message\n  \"\"\"\n  error: String!\n}\n\n# ============================================================================\n# ENUMS\n# ============================================================================\n\n\"\"\"\nBackup type enumeration\n\"\"\"\nenum BackupType {\n  \"\"\"\n  File-level database backup\n  \"\"\"\n  FILE\n\n  \"\"\"\n  Table-level JSON backup\n  \"\"\"\n  TABLE\n\n  \"\"\"\n  All backup types\n  \"\"\"\n  ALL\n}\n\n# ============================================================================\n# QUERIES\n# ============================================================================\n\nextend type Query {\n  \"\"\"\n  List all available backups\n  \"\"\"\n  listBackups(filter: BackupListFilterInput): BackupListResult!\n\n  \"\"\"\n  Get backup metrics and statistics\n  \"\"\"\n  backupMetrics: BackupMetrics!\n}\n\n# ============================================================================\n# MUTATIONS\n# ============================================================================\n\nextend type Mutation {\n  \"\"\"\n  Create a full database backup\n\n  Creates a complete SQLite database backup with optional compression and validation.\n  Uses VACUUM INTO for clean backup or falls back to file copy.\n  \"\"\"\n  backupDatabase(input: BackupDatabaseInput): BackupDatabaseResult!\n\n  \"\"\"\n  Restore database from backup\n\n  Restores the entire database from a backup file.\n  WARNING: Requires server restart to take effect.\n  \"\"\"\n  restoreDatabase(input: RestoreDatabaseInput!): RestoreDatabaseResult!\n\n  \"\"\"\n  Apply backup retention policy\n\n  Automatically delete old backups based on retention rules.\n  Helps manage disk space and backup organization.\n  \"\"\"\n  applyRetentionPolicy(policy: BackupRetentionPolicyInput!): ApplyRetentionPolicyResult!\n}\n",
