    sdl: "# JSON Export type definitions\n# Supports Flat JSON and HFI Protocol formats\n\n# Export format enum\nenum JsonExportFormat {\n  FLAT\n  HFI\n}\n\n# Export options\ninput JsonExportOptions {\n  \"\"\"\n  Export format: FLAT for simple array, HFI for full graph protocol\n  \"\"\"\n  format: JsonExportFormat! = FLAT\n  \"\"\"\n  Include relations as branches (HFI only)\n  \"\"\"\n  includeRelations: Boolean = true\n  \"\"\"\n  Include node positions (HFI only)\n  \"\"\"\n  includePositions: Boolean = false\n  \"\"\"\n  Include visual themes (HFI only)\n  \"\"\"\n  includeThemes: Boolean = false\n  \"\"\"\n  Include state connections (HFI only)\n  \"\"\"\n  includeStateConnections: Boolean = false\n  \"\"\"\n  Pretty print JSON output\n  \"\"\"\n  prettyPrint: Boolean = true\n  \"\"\"\n  Filter by specific node IDs\n  \"\"\"\n  nodeIds: [String!]\n  \"\"\"\n  Filter by tags\n  \"\"\"\n  tags: [String!]\n}\n\n# Flat JSON node structure\ntype FlatJsonNode {\n  id: String!\n  title: String!\n  content: String\n  \"\"\"\n  Dynamic attributes as key-value pairs\n  \"\"\"\n  attributes: JSON\n}\n\n# Flat JSON export result\ntype FlatJsonExport {\n  version: String!\n  exportedAt: String!\n  table: FlatJsonTableInfo!\n  nodes: [FlatJsonNode!]!\n}\n\ntype FlatJsonTableInfo {\n  id: String!\n  identifier: String!\n  description: String\n}\n\n# HFI Protocol types\ntype HFIBranchMetadata {\n  case: String!\n  label: String\n  description: String\n  next: JSON\n  color: String\n  condition: JSON\n  meta: JSON\n}\n\ntype HFIPayloadField {\n  key: String!\n  type: String!\n  value: JSON!\n  default: JSON\n  required: Boolean\n  enum: [JSON!]\n  min: Float\n  max: Float\n  step: Float\n  pattern: String\n  widget: String\n  direction: String\n  stateFrom: JSON\n}\n\ntype HFIFlowNode {\n  id: String!\n  type: String!\n  target: String!\n  title: String!\n  position: JSON\n  flowContext: String\n  category: String\n  tags: [String!]\n  style: JSON\n  branches: [HFIBranchMetadata!]\n  payload: [HFIPayloadField!]!\n  description: String\n}\n\ntype HFIFlowEdge {\n  id: String!\n  label: String\n  animated: Boolean\n  style: JSON\n}\n\ntype HFIStateConnection {\n  from: String!\n  fromField: String!\n  to: String!\n  toField: String!\n}\n\ntype HFIProtocolMetadata {\n  createdAt: String\n  updatedAt: String\n  author: String\n  description: String\n  version: String\n  tags: [String!]\n  sourceTable: JSON\n}\n\ntype HFIProtocolExport {\n  protocol: String!\n  context: String!\n  nodes: [HFIFlowNode!]!\n  edges: [HFIFlowEdge!]!\n  stateConnections: [HFIStateConnection!]\n  viewport: JSON\n  themes: JSON\n  metadata: HFIProtocolMetadata\n}\n\n# Union type for export result data\nunion JsonExportData = FlatJsonExport | HFIProtocolExport\n\n# JSON export result\ntype JsonExportResult {\n  success: Boolean!\n  format: JsonExportFormat!\n  \"\"\"\n  Raw JSON string output\n  \"\"\"\n  json: String\n  \"\"\"\n  Parsed data (use json field for actual export)\n  \"\"\"\n  data: JSON\n  nodeCount: Int!\n  errors: [String!]!\n  warnings: [String!]!\n}\n\nextend type Query {\n  \"\"\"\n  Export table data to JSON format (Flat or HFI Protocol)\n  \"\"\"\n  exportTableJson(tableId: String!, options: JsonExportOptions): JsonExportResult!\n}\n",
